def _conv_tiled(k, x, w, out):
    B, C, H, _ = x.shape
    K = w.shape[2]
    O = H - K + 1
    nw = w.numel()
    wt = _WT.get(nw)
    if wt is None:
        wt = _WT[nw] = torch.empty(nw, dtype=torch.float32, device="cuda")
    dims = _dims(C, H, K, B)
    P = lambda t: t.data_ptr()
