        m = torch.arange(32, dtype=torch.float64)
        tw = torch.cat([torch.cos(2 * _math.pi * m / 64), -torch.sin(2 * _math.pi * m / 64)]).float().cuda()
        nxf, nwf = C * NBTP * 2112, C * C * 2112
